(function(){'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}),integer=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0});
const money=v=>v===null||v===undefined?'—':num.format(v)+' ₽',date=v=>v?new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'нет снимка',short=v=>new Date(v+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'2-digit',month:'short'}),shift=(date,days)=>new Date(Date.parse(date+'T12:00:00Z')+days*86400000).toISOString().slice(0,10);
const definitions={
 orderedRevenue:['Заказано на сумму','Заказы Ozon до отмен и возвратов. Это не оплаченные продажи. Метрика revenue из /v1/analytics/data.','up'],
 orderedUnits:['Заказано товаров','Количество заказанных единиц, включая заказы, которые могут быть отменены. Метрика ordered_units из /v1/analytics/data.','up'],
 realized:['Реализация','Сумма sale_amount по дате финансового начисления, с учётом отрицательных корректировок. Включает баллы за скидки и партнёрские начисления.','up'],
 net:['Итог начислений','Общий результат всех начислений Ozon после удержаний. Не является чистой прибылью или суммой уже выведенных денег.','up'],
 commission:['Комиссия Ozon','Итоговая комиссия с учётом скидок и наценок; возвращённые комиссии уменьшают расход.','down'],
 logistics:['Логистика и доставка','Доставка из posting.delivery, обратная логистика, кросс-докинг и связанные услуги. Разбивка использует справочник Ozon; полный состав виден в расшифровке удержаний.','down'],
 ads:['Реклама и продвижение','Удержания за оплату за клик, продвижение и другие рекламные услуги из финансовых начислений. Это фактические начисления, без статистики показов и конверсий рекламных кабинетов.','down'],
 adShare:['Реклама / реализация','Расходы на рекламу и продвижение / реализация × 100%. Доля считается по датам начислений; она не равна ДРР рекламного кабинета.','down'],
 acquiring:['Эквайринг','Удержания типа Acquiring из справочника Ozon с учётом корректировок.','down'],
 storage:['Размещение и хранение','Размещение на складах Ozon, временное хранение у партнёров и хранение возвратов.','down'],
 other:['Прочие начисления','Прочие услуги и корректировки, включая подписки, страхование, гибкие выплаты и товарные компенсации. Положительная сумма карточки означает чистое удержание, отрицательная — начисление продавцу.','down'],
 penalties:['Штрафы и ошибки','Услуги по операционным ошибкам и штрафы из справочника Ozon.','down'],
 bonus:['Баллы за скидки','Поле commission.bonus. Уже входят в реализацию; повторно прибавлять их к доходу нельзя.','neutral'],
 partners:['Программа партнёров','Поле commission.coinvestment. Уже учтено в реализации; это не дополнительная сумма сверх неё.','neutral'],
 reversal:['Отрицательная реализация','Модуль отрицательных sale_amount: возвраты и другие сторнирующие корректировки. Не является количеством возвращённых товаров.','down'],
 stocks:['Товаров в остатке','Текущий снимок Ozon: сумма present, без вычитания резерва. Не зависит от выбранного периода. Неизвестные остатки исключены.','neutral'],
 stockValue:['Остатки по себестоимости','Текущий остаток × текущая заполненная себестоимость Ozon в рублях. Это оценка только известных позиций, не стоимость всех запасов по бухгалтерскому учёту.','neutral'],
 zeroStock:['Позиций без остатка','Количество карточек Ozon с известным нулевым остатком в текущем снимке.','down'],
 costCoverage:['Себестоимость заполнена','Доля карточек Ozon с положительной заполненной себестоимостью в текущем каталоге.','up']
};
const groupNames={commission:'Комиссия',logistics:'Логистика',ads:'Продвижение',acquiring:'Эквайринг',storage:'Хранение',penalties:'Штрафы',other:'Прочее'};
const defaults=['orderedRevenue','orderedUnits','realized','net','commission','logistics','ads','adShare','acquiring','storage','other','bonus','partners','reversal','stocks','stockValue'];
let enabled=new Set(defaults),report=null,busy=false,pending=false,generation=0,productPage=1,productRows=[];
try{const saved=JSON.parse(localStorage.getItem('pult-widgets-v1'));if(Array.isArray(saved)&&saved.some(k=>definitions[k]))enabled=new Set(saved.filter(k=>definitions[k]))}catch{}
$('metrics').insertAdjacentHTML('beforebegin',`<section id="executive"><div class="ins-heading"><div><h2>Управленческая сводка <span class="platform">Ozon</span></h2><p>Заказы, реализация и расходы четырёх магазинов</p></div><div class="ins-actions"><button id="ins-refresh" class="button">↻ Обновить из Ozon</button><button id="ins-widgets" class="button secondary">⚙ Виджеты</button></div></div><div class="ins-period"><label>Период<select id="ins-range"><option value="7">7 завершённых дней</option><option value="14">14 завершённых дней</option><option value="30">30 дней по сегодня</option><option value="custom">Выбрать даты</option></select></label><label>С<input id="ins-from" type="date"></label><label>По<input id="ins-to" type="date"></label><div id="ins-comparison"></div></div><div id="ins-state" role="status" aria-live="polite">Готовим расширенную аналитику…</div><div id="ins-metrics" class="ins-metrics"></div><div class="ins-two"><section class="panel"><div class="panel-heading"><div><h2>Динамика бизнеса</h2><p id="ins-chart-caption">По дням выбранного периода</p></div><label class="ins-chart-label">Показатель<select id="ins-chart-metric"><option value="realized">Реализация</option><option value="net">Итог начислений</option><option value="orderedRevenue">Заказано на сумму</option><option value="orderedUnits">Заказано товаров</option><option value="ads">Реклама</option></select></label></div><div id="ins-chart"></div></section><section class="panel"><div class="panel-heading"><div><h2>Структура удержаний</h2><p>С учётом корректировок</p></div></div><div id="ins-expenses"></div><button id="ins-fees" class="ins-details-link">Расшифровать услуги Ozon →</button></section></div><div class="ins-quality" id="ins-quality"></div><section class="panel"><div class="panel-heading"><div><h2>Результат по магазинам</h2><p>Один период и единые правила расчёта</p></div></div><div class="table-wrap"><table><thead><tr><th>Магазин</th><th class="numeric">Реализация</th><th class="numeric">Комиссия</th><th class="numeric">Логистика</th><th class="numeric">Продвижение</th><th class="numeric">Итог начислений</th></tr></thead><tbody id="ins-stores"></tbody></table></div></section><section class="panel" id="ins-products-panel"><div class="panel-heading"><div><h2>Товары: вклад в реализацию</h2><p>Финансовые операции с привязкой к SKU</p></div><button class="button secondary" id="ins-export">↓ Скачать CSV</button></div><div class="product-controls"><label class="search-label">Найти товар<input id="ins-search" type="search" placeholder="Название, артикул, SKU"></label><label>Сортировка<select id="ins-sort"><option value="realized">По реализации ↓</option><option value="net">По начислениям ↓</option><option value="logistics">По логистике ↓</option></select></label></div><div class="table-wrap"><table><thead><tr><th>Товар / артикул</th><th>Магазин</th><th class="numeric">Реализация</th><th class="numeric">Комиссия</th><th class="numeric">Логистика</th><th class="numeric">Начисления по SKU</th><th></th></tr></thead><tbody id="ins-product-rows"></tbody></table></div><div class="pagination"><span id="ins-product-count"></span><div><button id="ins-prev" class="button secondary" aria-label="Предыдущие товары">←</button><span id="ins-page"></span><button id="ins-next" class="button secondary" aria-label="Следующие товары">→</button></div></div><p class="footnote">Начисления по SKU не являются прибылью: общие услуги магазина и часть рекламы не распределены по товарам. Исторические операции включают архивные товары. Чистая прибыль требует себестоимости на дату продажи, налогов и внешних расходов.</p></section><p class="ins-source" id="ins-source"></p></section><div id="ins-wb" class="ins-quality" hidden>Расширенная управленческая сводка сейчас доступна для Ozon. Каталог, остатки и загруженные отчёты WB показаны ниже.</div>`);
document.body.insertAdjacentHTML('beforeend',`<dialog id="ins-settings"><div class="dialog-top"><span class="eyebrow">НАСТРОЙКА ГЛАВНОГО ЭКРАНА</span><button class="button secondary" data-ins-close="ins-settings" aria-label="Закрыть настройку виджетов">✕</button></div><h2 class="detail-title">Твои ключевые показатели</h2><p>Выбери карточки для главного экрана. Настройка сохранится в этом браузере.</p><div id="ins-widget-list"></div><button id="ins-widget-reset" class="button secondary">Вернуть набор по умолчанию</button></dialog><dialog id="ins-detail"><div class="dialog-top"><span class="eyebrow">ИСТОЧНИК И РАСЧЁТ</span><button class="button secondary" data-ins-close="ins-detail" aria-label="Закрыть расшифровку">✕</button></div><div id="ins-detail-content"></div></dialog>`);
async function api(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const d=await r.json();if(!r.ok)throw Error(d.error||'Не удалось загрузить аналитику');return d}
function setRange(){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),days=Number($('ins-range').value);if(days){$('ins-to').value=days===30?today:shift(today,-1);$('ins-from').value=shift($('ins-to').value,1-days)}}setRange();
async function load(){const seq=++generation;if(busy){pending=true;return}if($('market').value==='WB'||$('store').value.startsWith('wb-')){$('executive').hidden=true;$('ins-wb').hidden=false;$('metrics').classList.add('legacy-visible');return}$('executive').hidden=false;$('ins-wb').hidden=true;$('metrics').classList.remove('legacy-visible');busy=true;
 try{const query=new URLSearchParams({from:$('ins-from').value,to:$('ins-to').value,store:$('store').value,hideInactive:String($('hide-inactive').checked)}),value=await api('/api/insights?'+query);if(seq!==generation)return;report=value;render();}catch(e){$('ins-state').textContent=e.message+' · Показан последний успешно загруженный отчёт.';$('ins-state').className='ins-alert';}finally{busy=false;if(pending){pending=false;void load()}}}
function render(){const {current,previous,coverage}=report;$('ins-comparison').textContent='Сравнение: '+short(previous.from)+' — '+short(previous.to);const active=Object.values(report.jobs||{}).some(j=>j.status==='running')||(report.syncJobs||[]).some(j=>j?.status==='running');$('ins-refresh').disabled=active;$('ins-refresh').textContent=active?'↻ Данные обновляются…':'↻ Обновить из Ozon';
 const notes=[];if(coverage.unreconciledRecords)notes.push('Требуют разбора '+coverage.unreconciledRecords+' начислений. Нерасшифрованная сумма: '+money(coverage.unreconciled));if(!coverage.finance)notes.push('Финансовый период загружен не полностью. Доступные даты: '+(coverage.financeFrom||'—')+' — '+(coverage.financeTo||'—'));if(!coverage.orders)notes.push('Не во всех выбранных магазинах загружена аналитика заказов');if(!coverage.previousFinance)notes.push('Для части сравнений нет полного предыдущего финансового периода');if(active)notes.push('Идёт импорт. Пока показаны последние завершённые снимки');if(coverage.foreignRecords)notes.push('В сводке только рубли: другие валюты не суммируются');for(const source of report.sources)for(const error of source.errors)notes.push(source.name+': '+error);
 $('ins-state').className=notes.length?'ins-alert':'ins-proof';$('ins-state').textContent=notes.length?[...new Set(notes)].join(' · '):'✓ Начисления сверены: '+integer.format(coverage.records)+' записей за период · '+(coverage.unreconciled===0?'расхождений нет':'нерасшифрованный остаток '+money(coverage.unreconciled));
 renderMetrics();renderChart();renderExpenses();renderStores();renderProducts();
 $('ins-quality').innerHTML=`<div><b>Что требует внимания</b><p>${integer.format(report.metrics.zeroStock.current??0)} карточек с нулевым остатком · ${integer.format(coverage.unknownStocks)} с неизвестным.</p></div><button class="button secondary" id="ins-open-zero">Проверить остатки →</button><button class="button secondary" id="ins-open-cost">Проверить себестоимость →</button>`;
 $('ins-open-zero').onclick=()=>openCatalog('zero');$('ins-open-cost').onclick=()=>openCatalog('cost');
 $('ins-source').textContent='Источники: Ozon Seller API. '+report.sources.map(s=>s.name+': заказы '+date(s.ordersAt)+', финансы '+date(s.financeAt)).join(' · ')+'. При работе на этой странице заказы, справочник и устаревшие снимки Ozon обновляются раз в 6 часов. Пока идёт импорт, показан последний завершённый снимок. Оценка запасов включает '+coverage.valuedStockProducts+' карточек с известной себестоимостью из '+coverage.knownStockProducts+' с известным остатком.';
}
function metricValue(m,exact=false){if(m.current===null)return '—';const f=m.kind==='money'?(exact?num:Math.abs(m.current)>=100000?integer:num):m.kind==='units'?integer:num;return f.format(m.current)+(m.kind==='money'?' ₽':m.kind==='percent'?'%':'')}
function renderMetrics(){$('ins-metrics').innerHTML=Object.keys(definitions).filter(k=>enabled.has(k)).map(key=>{const m=report.metrics[key],def=definitions[key];let diff='Нет данных для сравнения',tone='';if(m.source==='inventory')diff='Текущий снимок · вне периода';else if(m.current!==null&&m.previous!==null){const delta=m.current-m.previous,pct=m.previous===0?null:delta/Math.abs(m.previous)*100;const good=def[2]==='up'?delta>0:def[2]==='down'?delta<0:null;tone=delta===0||good===null?'':good?'good':'bad';diff=(delta>0?'↑ ':delta<0?'↓ ':'')+(m.kind==='percent'?num.format(Math.abs(delta))+' п.п.':pct===null?(delta===0?'Без изменений':'Предыдущий период: 0'):num.format(Math.abs(pct))+'%')+' · было '+metricValue({...m,current:m.previous});}return `<button class="ins-metric ${tone}" data-ins-metric="${key}" title="${esc(def[1])}"><span class="ins-metric-name">${def[0]} <i>ⓘ</i></span><strong title="${esc(metricValue(m,true))}">${metricValue(m)}</strong><span class="ins-delta">${esc(diff)}</span></button>`}).join('')}
function renderChart(){const key=$('ins-chart-metric').value,points=report.daily.filter(p=>p[key]!==null),title=definitions[key][0];$('ins-chart-caption').textContent=title+' · '+short(report.current.from)+' — '+short(report.current.to);if(!points.length){$('ins-chart').innerHTML='<div class="empty">Для этого периода данные ещё не загружены.</div>';return}
 const W=760,H=230,L=68,R=18,T=15,B=35,lo=Math.min(0,...points.map(p=>p[key])),hi=Math.max(1,...points.map(p=>p[key])),x=i=>L+(W-L-R)*(points.length===1?.5:i/(points.length-1)),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)} по дням">`;for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3,yy=y(v);svg+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#eaf0f8"/><text x="${L-10}" y="${yy+4}" text-anchor="end">${num.format(Math.abs(v)>=1000000?v/1000000:Math.abs(v)>=1000?v/1000:v)}${Math.abs(v)>=1000000?'м':Math.abs(v)>=1000?'к':''}</text>`}
 const path=points.map((p,i)=>(i?'L':'M')+x(i)+','+y(p[key])).join(' ');svg+=`<path d="${path} L${x(points.length-1)},${y(0)} L${x(0)},${y(0)} Z" fill="#315efb0d"/><path d="${path}" fill="none" stroke="#5276ef" stroke-width="3" stroke-linejoin="round"/>`;points.forEach((p,i)=>{svg+=`<circle cx="${x(i)}" cy="${y(p[key])}" r="4" fill="#5276ef"><title>${short(p.date)}: ${key==='orderedUnits'?integer.format(p[key]):money(p[key])}</title></circle>`;if(i===0||i===points.length-1||i%Math.max(1,Math.ceil(points.length/6))===0)svg+=`<text x="${x(i)}" y="${H-10}" text-anchor="middle">${short(p.date)}</text>`});$('ins-chart').innerHTML=svg+'</svg>';
}
function renderExpenses(){if(!report.coverage.finance){$('ins-expenses').innerHTML='<div class="empty">Выберите полностью загруженный период.</div>';return}const rows=Object.keys(groupNames).map(key=>({key,title:groupNames[key],value:report.metrics[key].current})),sum=rows.reduce((s,r)=>s+Math.max(0,r.value||0),0);$('ins-expenses').innerHTML=rows.map(r=>`<button class="ins-expense" data-expense="${r.key}"><span>${r.title}</span><b>${money(r.value)}</b><i><em style="width:${sum?Math.max(0,r.value)/sum*100:0}%"></em></i></button>`).join('')}
function renderStores(){$('ins-stores').innerHTML=report.stores.map(s=>`<tr><td><strong>${esc(s.name)}</strong>${s.complete?'':'<span class="sub">Неполный период</span>'}</td>${['realized','commission','logistics','ads','net'].map(k=>`<td class="numeric">${s.complete?money(s[k]):'—'}</td>`).join('')}</tr>`).join('')}
function renderProducts(){const q=$('ins-search').value.trim().toLocaleLowerCase('ru-RU'),sort=$('ins-sort').value;productRows=report.products.filter(p=>!q||[p.name,p.offer_id,p.sku,p.storeName].join(' ').toLocaleLowerCase('ru-RU').includes(q)).sort((a,b)=>b[sort]-a[sort]);productPage=Math.max(1,Math.min(productPage,Math.ceil(productRows.length/15)||1));const rows=productRows.slice((productPage-1)*15,productPage*15);$('ins-product-rows').innerHTML=!report.coverage.finance?'<tr><td colspan="7" class="empty">Для выбранного периода нет полного финансового снимка.</td></tr>':rows.map(p=>`<tr><td><span class="ins-product-name" title="${esc(p.name)}">${esc(p.name)}</span><span class="sub">${esc(p.offer_id)} · SKU ${esc(p.sku)}${p.archived?' · архив':''}</span></td><td>${esc(p.storeName)}</td><td class="numeric">${money(p.realized)}</td><td class="numeric">${money(p.commission)}</td><td class="numeric">${money(p.logistics)}</td><td class="numeric"><strong>${money(p.net)}</strong></td><td>${p.key?`<a class="button secondary" href="/manage.html?product=${encodeURIComponent(p.key)}">Управлять →</a>`:'—'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Нет товаров по выбранным условиям.</td></tr>';$('ins-product-count').textContent=report.coverage.finance?'Товаров с начислениями: '+integer.format(productRows.length):'Нет полного периода';$('ins-page').textContent=productPage+' / '+(Math.ceil(productRows.length/15)||1);$('ins-prev').disabled=productPage===1;$('ins-next').disabled=productPage*15>=productRows.length;$('ins-export').disabled=!report.coverage.finance||!productRows.length;}
function showMetric(key){if(!report)return;const m=report.metrics[key];$('ins-detail-content').innerHTML=`<h2 class="detail-title">${definitions[key][0]}</h2><div class="ins-detail-value">${metricValue(m,true)}</div><p>${esc(definitions[key][1])}</p><div class="detail-source">Период: ${short(report.current.from)} — ${short(report.current.to)}<br>Предыдущий: ${short(report.previous.from)} — ${short(report.previous.to)}<br>Значение предыдущего периода: ${m.previous===null?'нет полного снимка':metricValue({...m,current:m.previous},true)}</div>${m.source==='inventory'?'<p>Показатель относится к текущему состоянию склада, а не к выбранному периоду продаж.</p>':''}<p>Источник: ${m.source==='finance'?'/v1/finance/accrual/by-day':m.source==='orders'?'/v1/analytics/data':'/v4/product/info/stocks и /v5/product/info/prices'}.</p>${groupNames[key]?'<button class="button secondary" id="ins-detail-fees">Открыть состав услуг</button>':''}`;if($('ins-detail-fees'))$('ins-detail-fees').onclick=()=>showFees(key);$('ins-detail').showModal()}
function showFees(group){if(!report)return;const rows=report.fees.filter(f=>!group||f.group===group);$('ins-detail-content').innerHTML=`<h2 class="detail-title">${group?groupNames[group]:'Услуги и корректировки Ozon'}</h2><p>Названия получены из справочника Ozon. Минус — удержание, плюс — начисление. Комиссия из отправлений показана отдельной карточкой.</p><div class="table-wrap"><table><thead><tr><th>Услуга</th><th class="numeric">Сумма</th><th class="numeric">Строк</th></tr></thead><tbody>${rows.map(f=>`<tr><td class="ins-fee-name">${esc(f.name)}</td><td class="numeric">${money(f.amount)}</td><td class="numeric">${integer.format(f.count)}</td></tr>`).join('')||'<tr><td colspan="3">Нет отдельных услуг этой группы за период.</td></tr>'}</tbody></table></div>`;if(!$('ins-detail').open)$('ins-detail').showModal()}
function openCatalog(issue){if($('market').value!=='Ozon'){$('market').value='Ozon';$('market').dispatchEvent(new Event('change'))}$('issue').value=issue;$('search').value='';$('issue').dispatchEvent(new Event('change'));location.hash='products'}
function widgetSettings(){$('ins-widget-list').innerHTML=Object.entries(definitions).map(([key,def])=>`<label><input type="checkbox" data-widget="${key}" ${enabled.has(key)?'checked':''}> ${def[0]}</label>`).join('')}
$('ins-widgets').onclick=()=>{widgetSettings();$('ins-settings').showModal()};$('ins-widget-list').onchange=e=>{const key=e.target.dataset.widget;if(!key)return;e.target.checked?enabled.add(key):enabled.delete(key);if(!enabled.size){enabled.add(key);e.target.checked=true}try{localStorage.setItem('pult-widgets-v1',JSON.stringify([...enabled]))}catch{}if(report)renderMetrics()};$('ins-widget-reset').onclick=()=>{enabled=new Set(defaults);try{localStorage.removeItem('pult-widgets-v1')}catch{}widgetSettings();if(report)renderMetrics()};for(const button of document.querySelectorAll('[data-ins-close]'))button.onclick=()=>$(button.dataset.insClose).close();
$('ins-range').onchange=()=>{setRange();void load()};for(const id of ['ins-from','ins-to'])$(id).onchange=()=>{$('ins-range').value='custom';void load()};for(const id of ['market','store','hide-inactive'])$(id).addEventListener('change',()=>void load());
$('ins-metrics').onclick=e=>{const b=e.target.closest('[data-ins-metric]');if(b)showMetric(b.dataset.insMetric)};$('ins-expenses').onclick=e=>{const b=e.target.closest('[data-expense]');if(b)showFees(b.dataset.expense)};$('ins-fees').onclick=()=>showFees();$('ins-chart-metric').onchange=()=>{if(report)renderChart()};$('ins-search').oninput=()=>{productPage=1;if(report)renderProducts()};$('ins-sort').onchange=()=>{productPage=1;if(report)renderProducts()};$('ins-prev').onclick=()=>{productPage--;renderProducts()};$('ins-next').onclick=()=>{productPage++;renderProducts()};
$('ins-refresh').onclick=async()=>{$('ins-refresh').disabled=true;try{await api('/api/insights/refresh',{store:$('store').value});await load()}catch(e){$('ins-state').textContent=e.message;$('ins-state').className='ins-alert';$('ins-refresh').disabled=false}};
$('ins-export').onclick=()=>{const cell=v=>{let s=String(v??'');if(/^\s*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'},rows=[['Период с','Период по','Магазин','Артикул','SKU','Товар','Реализация RUB','Комиссия RUB','Логистика RUB','Начисления по SKU RUB'],...productRows.map(p=>[report.current.from,report.current.to,p.storeName,p.offer_id,p.sku,p.name,p.realized,p.commission,p.logistics,p.net])],url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Пульт-реализация-'+report.current.from+'-'+report.current.to+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
void load();setInterval(()=>{if(!document.hidden)void load()},30000);
})();
